        left = operands.pop()
        right = operands.pop()
        if operator == '+':
            return left + right
        elif operator == '-':
            return left - right
        elif operator == '*':
            return left * right
        elif operator == '/':
            return left // right  # Integer floor division

    def greater_precedence(op1, op2):
        precedences = {'+': 1, '-': 1, '*': 2, '/': 2}
        return precedences[op1] > precedences[op2]

    def shunting_yard(parsed_expr):
        output_queue = []
        operator_stack = []
        for token in parsed_expr:
            if token.isdigit():
                output_queue.append(int(token))
            continue
            elif token in '+-':
                while operator_stack and greater_precedence(operator_stack[-1], token):
                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                break
        while operator_stack:
            op = operator_stack.pop()
            output_queue.append(op)
        return output_queue

    def evaluate(rpn_queue):
        operands = []
        for token in rpn_queue:
            if token in '+-*/':
                right = operands.pop()
                left = operands.pop()
                operands.append(apply_operator(left, token, right))
            else:
                operands.append(token)
        return operands[0]

    def parse(expr):
        number = ''
        for char in expr:
            if char.isdigit():
                number += char
            elif char in '+-*/()':
                yield number
                number = ''
        yield number  # Yield the last number in the expression

    # Convert the expression to Reverse Polish Notation (RPN)
    rpn_queue = shunting_yard(parse(expr))
    # Evaluate the RPN expression
    return evaluate(rpn_queue)

