class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head = None  # Represents the tail of the doubly linked list
        self.tail = self.head

    def _add_node(self, key, value):
        new_node = {'key': key, 'value': value}
        new_node['prev'] = None
        new_node['next'] = self.tail
        if self.tail:
            self.tail.next = new_node
        self.tail = new_node
        if not self.head:
            self.head = new_node

    def _remove_node(self, node):
        prev = node.prev
        next = node.next
        if prev:
            prev.next = next
        else:
            self.head = next
        if next:
            next.prev = prev
        else:
            self.tail = prev

    def _move_to_front(self, node):
        self._remove_node(node)
        self._add_node(node.key, node.value)

    def get(self, key):
        node = self.cache.get(key, None)
        if node:
            self._move_to_front(node)
            return node['value']
        return -1

    def put(self, key, value):
        node = self.cache.get(key)
        if node:
            node['value'] = value
            self._move_to_front(node)
        else:
            new_node = {'key': key, 'value': value}
            self._add_node(new_node)
            if len(self.cache) > self.capacity:
                last = self.tail
                self._remove_node(last)

