    # Create a map from task to its dependencies
    incoming_edges = {task: set() for task in deps}
    for task, dependencies in deps.items():
        for dep in dependencies:
            incoming_edges[dep].add(task)

    # Find tasks with no incoming edges
    no_incoming = {task for task, incoming in incoming_edges.items() if not incoming}

    # Initialize the sorted list with tasks having no incoming edges
    sorted_tasks = sorted(no_incoming)

    # While there are tasks to process
    while no_incoming:
        current = sorted_tasks.pop()
        sorted_tasks.append(current)

        # Remove dependencies of the current task
        for task, dependencies in incoming_edges.items():
