            # If a task has no more dependencies, add it to the sorted tasks
            if not dependencies:
                sorted_tasks.append(task)
                sorted_tasks.sort()

    # Check if there were any tasks left with dependencies (which would indicate a cycle)
    if incoming_edges:
        raise ValueError("A cycle was detected in the task dependencies")

    return sorted_tasks

