    # Create a mapping from tasks to their dependencies
    incoming_edges = {task: set(deps) for task, deps in deps.items()}
    # Create a set to track tasks with no incoming edges
    no_incoming = {task for task, deps in incoming_edges.items() if not deps}

    # Initialize the sorted tasks list
    sorted_tasks = []

    # While there are tasks with no incoming edges
    while no_incoming:
        # Get the alphabetically smallest task from the no_incoming set
        current_task = min(no_incoming)
        no_incoming.remove(current_task)
        sorted_tasks.append(current_task)

        # Update the no_incoming set with tasks that only depend on the current task
        for task, deps in incoming_edges.items():
            if current_task in deps:
                deps.remove(current_task)
                if not deps:
                    no_incoming.add(task)

    # Check for cycles
    if any(incoming_edges.values()):
        raise ValueError("Cycle detected in task dependencies")

    return sorted_tasks

